import React, { useState } from "react";
import { postDataAPI } from "../utils/fetchData";
 
const DonationPage = () => {
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  const handleDonate = async () => {
    try {
      setLoading(true);
      setError("");

      // 🔥 reemplazo completo de fetch
      const { data } = await postDataAPI("checkout", {
        amount: 1000,
        currency: "dzd",
      });

      if (data.checkout_url) {
        window.location.href = data.checkout_url;
      } else {
        throw new Error("No checkout URL received");
      }
    } catch (err) {
      setError(
        err?.response?.data?.error ||
          err.message ||
          "Something went wrong"
      );
    } finally {
      setLoading(false);
    }
  };

  return (
    <div
      className="min-h-screen bg-gradient-to-b from-emerald-50 to-white"
      dir="rtl"
    >
      <div className="container mx-auto px-4 py-16">
        <div className="max-w-2xl mx-auto bg-white rounded-lg shadow-xl overflow-hidden">

          {/* Header */}
          <div className="bg-[#1B4B36] text-white p-8 text-center">
            <h1 className="text-3xl font-bold mb-4">
              حملة التبرعات الخيرية
            </h1>
            <p className="text-lg text-yellow-300">
              معاً لمستقبل أفضل
            </p>
          </div>

          {/* Body */}
          <div className="p-8">

            {/* Amount */}
            <div className="bg-emerald-50 p-6 rounded-lg text-center mb-8">
              <h3 className="text-xl font-bold text-[#1B4B36] mb-2">
                قيمة التبرع
              </h3>
              <p className="text-4xl font-bold text-[#1B4B36]">
                1000 دج
              </p>
            </div>

            {/* Button */}
            <button
              onClick={handleDonate}
              disabled={loading}
              className={`w-full font-bold py-4 px-8 rounded-lg transition-colors duration-200 text-lg ${
                loading
                  ? "bg-gray-400 cursor-not-allowed"
                  : "bg-[#1B4B36] hover:bg-[#153828] text-yellow-300"
              }`}
            >
              {loading ? "جاري التوجيه..." : "تبرع الآن"}
            </button>

            {/* Error */}
            {error && (
              <p className="text-red-500 text-center mt-4">
                {error}
              </p>
            )}

            {/* Trust message */}
            <div className="text-center text-sm text-gray-600 mt-6">
              <p>جميع التبرعات آمنة ومضمونة</p>
            </div>

          </div>
        </div>
      </div>
    </div>
  );
};
 
export default DonationPage;